pragma solidity >=0.8.0;

contract PackingProbe {
    uint8  public a;
    uint8  public b;
    bool   public c;
    int32  public d;
    uint16 public e;
    bool   public f;
    uint256 public g;

    function setAll(uint8 _a, uint8 _b, bool _c, int32 _d, uint16 _e, bool _f, uint256 _g) external {
        a = _a;
        b = _b;
        c = _c;
        d = _d;
        e = _e;
        f = _f;
        g = _g;
    }

    function writeReverse(uint8 _a, uint8 _b, bool _c) external {
        c = _c;
        b = _b;
        a = _a;
    }

    function clearSome() external {
        delete b;
        delete d;
        delete f;
    }

    function sum() external view returns (uint256) {
        uint256 s = uint256(a) + uint256(b) + uint256(e) + g;
        if (c) { s += 1000; }
        if (f) { s += 2000; }
        if (d < 0) { s += uint256(uint32(-d)); } else { s += uint256(uint32(d)); }
        return s;
    }
}

pragma solidity >=0.8.0;

contract EventProbe {
    uint256 public count;

    event One(address indexed who);
    event Two(address indexed who, uint256 indexed amount, bytes32 tag);
    event Three(address indexed a, uint256 indexed b, bool indexed c, string note);
    event DynIndexed(string indexed name, uint256 value);
    event Ctor(uint256 indexed start);

    constructor(uint256 start) {
        count = start;
        emit Ctor(start);
    }

    function emitAll(uint256 x) external {
        emit One(msg.sender);
        emit Two(msg.sender, x, bytes32(uint256(x) + 1));
        emit Three(msg.sender, x, x % 2 == 0, "hello");
        emit DynIndexed("same-string", x);
        emit DynIndexed("same-string", x);
        count += 5;
    }

    function emitOrdered(uint256 x) external {
        emit Two(msg.sender, x, bytes32(uint256(1)));
        emit One(msg.sender);
        emit Two(msg.sender, x + 1, bytes32(uint256(2)));
        emit One(msg.sender);
        count += 4;
    }
}

pragma solidity >=0.8.0;

contract IntEdgeSemantics {
    int16 public storedDiv;

    function storeDiv(int16 a, int16 b) public {
        storedDiv = a / b;
    }
}

pragma solidity >=0.8.0;

contract BlockHashProbe {
    function fetch() public returns (bytes32) {
        return blockhash(block.number);
    }
}
